public interface IEvictionPolicy<K> { K Pick(IReadOnlyList<K> keys); }
public sealed class LruPolicy<K> : IEvictionPolicy<K> { public K Pick(IReadOnlyList<K> keys) => keys[0]; }

public sealed class Cache<K, V, TPolicy> where TPolicy : IEvictionPolicy<K>, new()
{
    private readonly TPolicy _policy = new();
    public K ChooseVictim(IReadOnlyList<K> keys) => _policy.Pick(keys);
}
var lru = new Cache<string, int, LruPolicy<string>>();

public interface IEvictionPolicy<TSelf> where TSelf : IEvictionPolicy<TSelf>
{
    static abstract string Name { get; }
    static abstract int Pick(int[] keys);
}
public readonly struct Fifo : IEvictionPolicy<Fifo>
{
    public static string Name => "fifo";
    public static int Pick(int[] keys) => keys[0];
}
public static int Victim<P>(int[] keys) where P : IEvictionPolicy<P> => P.Pick(keys);

